{
"title": "Service Architecture",
"timeRange": {"from": "now-1h", "to": "now"},
"refreshIntervalMs": 15000,
"panels": [
{
"id": "service-map",
"title": "Service Map: Who Calls Whom",
"viz": "graph",
"description": "Maps every caller to callee edge with the total requests on that edge summed over the dashboard time range, grouped by caller, callee and tier.",
"query": {
"sourceId": "eval-demo-services",
"sql": "SELECT caller, callee, tier, SUM(requests) AS requests FROM service_calls GROUP BY caller, callee, tier"
},
"options": {
"layout": "dag",
"node": "block",
"direction": "LR",
"edgeLabels": true,
"source": "caller",
"target": "callee",
"value": "requests",
"group": "tier",
"symbols": {"service": "server", "store": "database"},
"compact": true
},
"layout": {"x": 0, "y": 0, "w": 12, "h": 8}
},
{
"id": "requests-received",
"title": "Requests Received per Service",
"viz": "bar",
"description": "Total requests received by each callee, summed across all its callers over the dashboard time range.",
"format": "number",
"query": {
"sourceId": "eval-demo-services",
"sql": "SELECT callee AS service, SUM(requests) AS received FROM service_calls GROUP BY callee ORDER BY received DESC"
},
"options": {"compact": true, "unit": "requests", "legend": "none"},
"layout": {"x": 0, "y": 8, "w": 6, "h": 4}
},
{
"id": "requests-sent",
"title": "Requests Sent per Service",
"viz": "bar",
"description": "Total requests sent by each caller, summed across all the services it calls over the dashboard time range.",
"format": "number",
"query": {
"sourceId": "eval-demo-services",
"sql": "SELECT caller AS service, SUM(requests) AS sent FROM service_calls GROUP BY caller ORDER BY sent DESC"
},
"options": {"compact": true, "unit": "requests", "legend": "none"},
"layout": {"x": 6, "y": 8, "w": 6, "h": 4}
}
]
}
